import{_ as n,a0 as l,w as i,s as p,ao as f,I as s,x as o,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"微軟將對應用商店中開源軟件的收費進行限制 | LCTT x X-CMD","titleTemplate":false,"description":"微軟將對應用商店中開源軟件的收費進行限制 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"微軟將對應用商店中開源軟件的收費進行限制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"微軟將對應用商店中開源軟件的收費進行限制 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store","title":"微軟將對應用商店中開源軟件的收費進行限制","tag":"202206","desc":""},"relativePath":"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store.md","filePath":"[post].md"}'),u={name:"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store.md"};function m(d,t,T,x,C,w){const e=l("Link");return i(),p("div",null,[t[15]||(t[15]=f('<h1 id="微軟將對應用商店中開源軟件的收費進行限制" tabindex="-1">微軟將對應用商店中開源軟件的收費進行限制 <a class="header-anchor" href="#微軟將對應用商店中開源軟件的收費進行限制" aria-label="Permalink to “微軟將對應用商店中開源軟件的收費進行限制”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/25/101648dlxnqxkaox00xc3l.jpg" alt=""></p><p>2022 年 6 月 16 日，微軟更新了其應用商店的策略。其中一項禁止了發佈者對開源或免費的軟件收取費用，另一項則針對的是商店使用的不合理高價。如果你在過去幾年中訪問過微軟應用商店，你可能已經注意到，它正在成為越來越多的開源和免費產品的所在地。如果原始開發者將應用程序和遊戲上傳到商店，這將是有益的，但情況並非如此，因為它們是由第三方上傳的。</p><p>更糟糕的是，其中許多程序僅作為付費應用提供，而不是免費下載。換句話説，微軟的客户必須付費才能購買應用商店的版本，而它們在其他地方是免費的！在應用商店中，免費版和付費版有時並存。為免費應用付費已經夠糟糕的了，但這並不是用户在購買時可能遇到的唯一問題。更新也可能是一個問題，因為山寨應用可能不會像源頭應用程序那樣頻繁或快速地更新。</p><p>在更新的微軟商店政策中，微軟在 10.8.7 節下指出：</p><blockquote><p>在您決定產品或應用內購買的定價時，您的數字產品或服務的所有定價（包括銷售或折扣）必須：</p><p>遵守所有適用的法律、法規和監管要求，包括聯邦貿易委員會的《反欺騙性定價指南》。您不得試圖從開源軟件或其他可免費獲得的軟件中獲利，您的產品也不應提供一個（與它提供的特性和功能相比）過高的不合理定價。</p></blockquote><p>這個新策略在更新部分中得到了確認。如果開源和免費產品普遍免費提供，則它們不得在微軟應用商店上出售，發佈者也不得對其產品收取不合理的高價。開源和免費應用的開發者可以在微軟應用商店上為其產品收費。例如，Paint.net 的開發者就是這樣做的。如果微軟強制執行這些策略，許多應用將從應用商店中刪除。以前，開發者可以向微軟報告應用程序，但在新策略下，微軟可以直接控制應用的列出和提交。</p><hr>',8)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),r(e,{href:"https://www.opensourceforu.com/2022/06/microsoft-to-charge-for-available-open-source-software-in-microsoft-store/"},{default:a(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/06/microsoft-to-charge-for-available-open-source-software-in-microsoft-store/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=o("作者：",-1)),r(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 選題：",-1)),r(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 譯者：",-1)),r(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[4]||(t[4]=[o("lkxed",-1)])]),_:1}),t[9]||(t[9]=o(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const k=n(u,[["render",m]]);export{b as __pageData,k as default};
